# Replica of SilenceDetector.overlapWalls + FillerDetector.conflict's wall test
# (app/Sources/SilenceDetector+Walls.swift:108, app/Sources/FillerDetector.swift:378).
# Times in seconds on a 30 fps grid.
import math

FPS = 30


def down(t):
    return math.floor(t * FPS) / FPS


def up(t):
    return math.ceil(t * FPS) / FPS


def wall(earlier, later):
    start = max(earlier[0], later[0])
    end = min(earlier[1], later[1])
    width = end - start
    assert width > 0
    return (down(max(0, start - width)), up(end + width)), (start, end)


def overlap(a, b):
    return max(0, min(a[1], b[1]) - max(a[0], b[0]))


A = (0.0, 11.0)
B = (10.0, 20.0)
w, real = wall(A, B)
print("real overlap", real, "wall", w)
for filler in [(9.3, 9.6), (10.2, 10.5), (11.4, 11.7), (8.5, 8.8)]:
    print(
        filler,
        "touches overlap" if overlap(filler, real) > 0 else "outside overlap",
        "-> .transition" if overlap(filler, w) > 0 else "-> kept",
    )

